def separate_paren_groups(paren_string):
    result = []
    depth = 0
    current = ''
    for char in paren_string.replace(' ', ''):
        if char == '(':
            depth += 1
            current += char
        elif char == ')':
            depth -= 1
            current += char
        else:
            if depth > 0:
                current += char
            elif depth == 0:
                result.append(current)
                current = char
    return result

