def heap_delete_insert(heap, x):
    heap[0] = x
    i = 1
    while i < len(heap):
        if i*2+1 >= len(heap):
            break
        elif i*2+1 == len(heap):
            if heap[i] > heap[i*2]:
                heap[i], heap[i*2] = heap[i*2], heap[i]
            break
        else:
            if heap[i] > heap[i*2] or heap[i] > heap[i*2+1]:
                if heap[i*2] <= heap[i*2+1]:
                    heap[i], heap[i*2] = heap[i*2], heap[i]
                    i = i*2
                else:
                    heap[i], heap[i*2+1] = heap[i*2+1], heap[i]
                    i = i*2 + 1
            else:
                break
    return heap[1:]

