def max_bi_tonic(arr):
    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]
    # Find longest increasing subsequence
    lis = [arr[i] for i in range(n)]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + arr[i])
    # Find longest decreasing subsequence
    lds = [arr[i] for i in range(n)]
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j]:
                lds[i] = max(lds[i], lds[j] + arr[i])
    # Find maximum value of lis[i] + lds[i] - arr[i]
    max_sum = lis[0] + lds[0] - arr[0]
    for i in range(1, n):
        max_sum = max(max_sum, lis[i] + lds[i] - arr[i])
    return max_sum

