    left = merge_sort(arr, l, mid)
    right = merge_sort(arr, mid + 1, r)

    return left + right + merge(arr, l, mid, r)


def merge(arr, l, m, r):
    i = l
    j = m + 1
    k = l
    temp = [0] * (r - l + 1)
    count = 0

    while i <= m and j <= r:
        if arr[i] <= arr[j]:
            temp[k] = arr[i]
            i += 1
        else:
            temp[k] = arr[j]
            count += (m - i + 1)
            j += 1
        k += 1

    while i <= m:
        temp[k] = arr[i]
        i += 1
        k += 1

    while j <= r:
        temp[k] = arr[j]
        j += 1
        k += 1

    for i in range(l, r + 1):
        arr[i] = temp[i]

    return count

