def goldmine(gold):
    if not gold:
        return 0

    rows = len(gold)
    cols = len(gold[0])

    # dp[i][j] is the maximum amount of gold that can be collected from cell (i, j) to the last column.
    dp = [[0 for _ in range(cols)] for _ in range(rows)]

    # Fill the last column of dp[][] from right to left.
    for i in range(rows):
        dp[i][-1] = gold[i][-1]

    # Fill the last row of dp[][] from right to left.
    for j in range(cols - 2, -1, -1):
        dp[-1][j] = gold[-1][j]

    # Fill the remaining cells of dp[][] from bottom to top and from right to left.
    for i in range(rows - 2, -1, -1):
        for j in range(cols - 2, -1, -1):
            # Find the maximum of three possible cells.
            max_cell = max(dp[i + 1][j], dp[i + 1][j + 1], dp[i][j + 1])
            dp[i][j] = gold[i][j] + max_cell

    # The result will be the maximum value in first column of dp[][].
    return max(dp[i][0] for i in range(rows))

