def countSub(arr,k):
    count = 0
    for i in range(len(arr)):
        prod = arr[i]
        if prod < k:
            count += 1
        for j in range(i+1,len(arr)):
            prod *= arr[j]
            if prod < k:
                count += 1
            else:
                break
    return count
